function dayOf(ms, tz) {
  return new Intl.DateTimeFormat("en-CA", { timeZone: tz }).format(ms);
}

function hourOf(ms, tz) {
  const text = new Intl.DateTimeFormat("en-US", { timeZone: tz, hour: "numeric", hourCycle: "h23" }).format(ms);
  return Number(text);
}

function isSameDay(aMs, bMs, tz) {
  const fmt = new Intl.DateTimeFormat("en-CA", { timeZone: tz });
  return fmt.format(aMs) === fmt.format(bMs);
}

function isWeekend(ms, tz) {
  const name = new Intl.DateTimeFormat("en-US", { timeZone: tz, weekday: "short" }).format(ms);
  return name === "Sat" || name === "Sun";
}

function greetingFor(ms, tz) {
  const hour = Number(new Intl.DateTimeFormat("en-US", { timeZone: tz, hour: "numeric", hourCycle: "h23" }).format(ms));
  if (hour < 12) return "morning";
  if (hour < 18) return "afternoon";
  return "evening";
}

function minutesSince(thenMs, nowMs) {
  return Math.floor((nowMs - thenMs) / 60000);
}

function isToday(timestampMs, timezone, nowMs) {
  const day = new Intl.DateTimeFormat("en-CA", { timeZone: timezone });
  return day.format(timestampMs) === day.format(nowMs);
}

function dayLabels(ms, zones) {
  return zones.map((zone) => {
    const day = new Intl.DateTimeFormat("en-CA", { timeZone: zone }).format(ms);
    return zone + ": " + day;
  });
}

