function isBusinessHours(ms, tz, startHour, endHour) {
  const hour = Number(new Intl.DateTimeFormat("en-US", { timeZone: tz, hour: "numeric", hourCycle: "h23" }).format(ms));
  return hour >= startHour && hour < endHour;
}

function reportWindow(nowMs, tz) {
  const day = new Intl.DateTimeFormat("en-CA", { timeZone: tz });
  return [day.format(nowMs - 24 * 60 * 60 * 1000), day.format(nowMs)];
}
